import java.util.ArrayList;
import java.util.List;

public class OrderTicketArchiveTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static List<Ticket> roundTrip(List<Ticket> tickets) {
        try {
            List<Ticket> back = OrderTicketArchive.unpack(OrderTicketArchive.pack(tickets));
            return back == null ? new ArrayList<>() : back;
        } catch (Exception e) {
            System.out.println("FAIL  round trip threw " + e.getClass().getSimpleName());
            failures++;
            return new ArrayList<>();
        }
    }

    public static void main(String[] args) {
        List<Ticket> tickets = new ArrayList<>();
        tickets.add(new Ticket("D4", 40));
        tickets.add(new Ticket("A1", 12));
        tickets.add(new Ticket("C3", 7));
        tickets.add(new Ticket("B2", 3));

        int packedLength = 0;
        try {
            byte[] packed = OrderTicketArchive.pack(tickets);
            packedLength = packed == null ? -1 : packed.length;
        } catch (Exception e) {
            System.out.println("FAIL  pack threw " + e.getClass().getSimpleName());
            failures++;
        }
        check("pack produces bytes", true, packedLength > 20);

        List<Ticket> back = roundTrip(tickets);
        check("restored size", 4, back.size());
        check("order preserved", tickets.toString(), back.toString());
        check("first ticket code", "D4", back.size() > 0 ? back.get(0).code() : "<missing>");
        check("last ticket seat", 3, back.size() > 3 ? back.get(3).seat() : -1);
        check("records compare by value", true, back.size() > 1 && back.get(1).equals(new Ticket("A1", 12)));

        List<Ticket> one = new ArrayList<>();
        one.add(new Ticket("Z9", 0));
        check("single ticket", "[Ticket[code=Z9, seat=0]]", roundTrip(one).toString());
        check("empty list", "[]", roundTrip(new ArrayList<Ticket>()).toString());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

