import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

record Ticket(String code, int seat) implements Serializable { }

public class OrderTicketArchive {

    public static byte[] pack(List<Ticket> tickets) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(new ArrayList<>(tickets));
        }
        return bytes.toByteArray();
    }

    @SuppressWarnings("unchecked")
    public static List<Ticket> unpack(byte[] data) throws IOException, ClassNotFoundException {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return (List<Ticket>) in.readObject();
        }
    }
}
